import React, { useState , useEffect }  from 'react';
import Swal from 'sweetalert2';
import 'bootstrap/dist/css/bootstrap.min.css';
import { useNavigate } from 'react-router-dom';
import config from './config'; // Archivo de configuración para la URL base
import axios from 'axios';
import './detalle_gestion.css';

const App = () => {
  const [promesas, setPromesas] = useState([]);
  const [idCampana, setIdCampana] = useState(null);
  const [idGestion, setIdGestion] = useState(null);
  const [idUsuario, setidUsuario] = useState(null);

  const [tipoGestionOptions, setTipoGestionOptions] = useState([]);
  const [tipologiaOptions, setTipologiaOptions] = useState([]);
  const [tipoDescuentoOptions, setTipoDescuentoOptions] = useState([]);
  const [subtipologiaOptions, setSubtipologiaOptions] = useState([]);
  const [razonMoraOptions, setRazonMoraOptions] = useState([]);
  const [tipoContactoOptions, setTipoContactoOptions] = useState([]);
  const [cuentaOptions, setCuentaOptions] = useState([]);

  const [formData, setFormData] = useState({
    cuenta: '',
    tipoGestion: '',
    tipologia: '',
    subtipologia: '',
    razonMora: '',
    tipoContacto: '',
    observaciones: '',
    investigacion: '',
    cantidadCuotas: '',
    fechaPago: '',
    descuento: '',
    tipoDescuento: '',
  });
  
  const getToken = () => {
      const token = localStorage.getItem('token');
      if (!token) {
        Swal.fire({
          icon: 'error',
          title: 'Error',
          text: 'No estás autenticado. Por favor, inicia sesión.',
        }).then(() => {
          localStorage.removeItem('token');
          window.location.href = '/';
        });
        return null;
      }
      return token;
  };
  
  const handleInputChange = (e) => {
    const { id, value } = e.target;
    setFormData({ ...formData, [id]: value });
  };

  const handleAgregarPromesa = () => {
    const { cuenta, cantidadCuotas, fechaPago, descuento, tipoDescuento } = formData;
  
    if (!cuenta || !cantidadCuotas || !fechaPago || !tipoDescuento) {
      Swal.fire({
        icon: 'error',
        title: 'Error',
        text: 'Todos los campos son obligatorios',
      });
      return;
    }
  
    // Obtener los elementos select
    const cuentaSelect = document.getElementById('cuenta');
    const tipoDescuentoSelect = document.getElementById('tipoDescuento');
  
    // Obtener los valores de data-item
    const cuentaItem = cuentaSelect.options[cuentaSelect.selectedIndex]?.innerText || '';
    const tipoDescuentoItem = tipoDescuentoSelect.options[tipoDescuentoSelect.selectedIndex]?.innerText || '';
  
    // Validar que se hayan encontrado valores válidos para cuenta y tipoDescuento
    if (!cuentaItem) {
      Swal.fire({
        icon: 'error',
        title: 'Error',
        text: 'Hubo un problema al obtener los valores de Cuenta.',
      });
      return;
    }

        // Validar que se hayan encontrado valores válidos para cuenta y tipoDescuento
        if (!tipoDescuentoItem) {
          Swal.fire({
            icon: 'error',
            title: 'Error',
            text: 'Hubo un problema al obtener los valores de Tipo de Descuento.',
          });
          return;
        }
  
    const nuevaPromesa = {
      cuenta: cuentaItem,
      cantidadCuotas,
      fechaPago,
      descuento: descuento || 0, // Asignar 0 si no se ha ingresado un descuento
      tipoDescuento: tipoDescuentoItem,
    };
  
    setPromesas((prevPromesas) => [...prevPromesas, nuevaPromesa]);
  
    // Limpiar solo los campos relacionados con las promesas
    setFormData({
      ...formData,
      cuenta: '',
      cantidadCuotas: '',
      fechaPago: '',
      descuento: '',
      tipoDescuento: '',
    });
  };
  
  const handleEliminarPromesa = (index) => {
    setPromesas((prevPromesas) => prevPromesas.filter((_, i) => i !== index));
  };
  
  const registrarGestion = async () => {
    try {
      // Obtener valores de los inputs y listados
      const bodyTipologia = {
        id_gestion: idGestion,
        id_tipogestion: formData.tipoGestion,
        id_tipologia: formData.tipologia,
        id_sub_tipologia: formData.subtipologia,
        id_razon_mora: formData.razonMora || 0, // Asignar 0 si no hay valor
        id_tipo_contacto: formData.tipoContacto || 0, // Asignar 0 si no hay valor
        observaciones: formData.observaciones,
        investigacion: formData.investigacion,
        id_usuario: idUsuario, // Asumimos que este valor está desencriptado y almacenado
      };

  
      // Consumir el primer endpoint (ingresar tipología)
      const response = await axios.post(`${config.API_BASE_URL}/ingresa-tipologia`, bodyTipologia, {
        headers: { Authorization: `Bearer ${getToken()}` },
      });
  
      const idTipologia = response.data.id_gestion;
  
      // Si el primer endpoint falla, no continuar
      if (!idTipologia) {
        Swal.fire('Error', 'No se pudo registrar la tipología.', 'error');
        return;
      }
  
      // Consumir el segundo endpoint para las promesas de pago
      const promesasFallidas = [];
      for (const promesa of promesas) {
        const bodyPromesa = {
          id_tipologia: idTipologia,
          id_gestion: idGestion,
          no_cuenta: promesa.cuenta,
          cant_cuotas: promesa.cantidadCuotas,
          fecha_pago: promesa.fechaPago,
          descuento: promesa.descuento,
          p_descuento: promesa.tipoDescuento,
          id_usuario: idUsuario,
        };
  
        try {
          await axios.post(`${config.API_BASE_URL}/ingresa-promesa-pago`, bodyPromesa, {
            headers: { Authorization: `Bearer ${getToken()}` },
          });

          // Remover de la lista las promesas exitosas
          setPromesas((prevPromesas) =>
            prevPromesas.filter((item) => item !== promesa)
          );

        } catch (error) {
          promesasFallidas.push(promesa);
        }
      }
  
      // Manejar errores en las promesas
      if (promesasFallidas.length > 0) {
        setPromesas(promesasFallidas); // Actualizar la tabla con las promesas fallidas
        bloquearCampos();
        Swal.fire(
          'Alerta',
          'La tipología se registró correctamente, pero algunas promesas de pago no pudieron ser ingresadas.',
          'warning'
        );
      } else {
        Swal.fire('Éxito', 'Gestión registrada correctamente.', 'success')
        .then(() => {
          window.location.reload(); // Recargar la página
        });
      }
    } catch (error) {
      Swal.fire('Error', 'Ocurrió un error al registrar la gestión.', 'error');
    }
  };

  const bloquearCampos = () => {
    // Bloquear todos los listados de opciones
    document.querySelectorAll('select').forEach((element) => {
      element.setAttribute('disabled', 'true');
    });
  
    // Bloquear todos los inputs de observaciones e investigación
    document.getElementById('observaciones').setAttribute('readonly', 'true');
    document.getElementById('investigacion').setAttribute('readonly', 'true');
  };
  
  const navigate = useNavigate();

  const redirectForm = () => {
    navigate(-1); // Regresa a la página anterior en el historial
  };

  const handleTipologiaChange = async (e) => {
    const selectedTipologia = e.target.value;
    setFormData({
      ...formData,
      tipologia: selectedTipologia,
      subtipologia: '',
      razonMora: '',
      tipoContacto: '',
    });
  
    setSubtipologiaOptions([]);
    setRazonMoraOptions([]);
    setTipoContactoOptions([]);
  
    try {
      const token = getToken();
      if (!token) return;
  
      const fetchDependentOptions = async (ddlValue, tipologiaValue, setStateCallback) => {
        try {
          const token = getToken();
          if (!token) return;
      
          const response = await axios.post(
            `${config.API_BASE_URL}/drops`,
            { id_campana: idCampana, ddl: ddlValue, id_tipologia: tipologiaValue },
            {
              headers: {
                Authorization: `Bearer ${token}`,
              },
            }
          );
      
          const data = response.data;
          setStateCallback(Array.isArray(data) ? data : []);
        } catch (error) {
          if (error.response && error.response.status === 500) {
            // Silenciar errores 401 y dejar el listado vacío
            setStateCallback([]);
          } else {
            Swal.fire('Error', `No se pudieron obtener los datos del listado: ${ddlValue}.`, 'error');
          }
        }
      };
      
  
      fetchDependentOptions('SUB_TIPOLOGIA', selectedTipologia, setSubtipologiaOptions);
      fetchDependentOptions('RAZON_MORA', selectedTipologia, setRazonMoraOptions);
      fetchDependentOptions('TIPO_CONTACTO', selectedTipologia, setTipoContactoOptions);
    } catch (error) {
      Swal.fire('Error', 'No se pudieron obtener las opciones dependientes.', 'error');
    }
  };

  const handleCuentaChange = async (e) => {
    const cuentaSeleccionada = e.target.value;
  
    // Actualizar el estado del formulario
    setFormData({ ...formData, cuenta: cuentaSeleccionada });
  
    try {
      const token = getToken();
      if (!token) return;
  
      const response = await axios.post(
        `${config.API_BASE_URL}/consulta-saldo-cuenta`,
        { id_gestion: idGestion, cuenta: cuentaSeleccionada },
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );
  
      const saldoCuenta = parseFloat(response.data[0]?.CUENTA || 0);
      const descuento = parseFloat(formData.descuento) || 0;
  
      const descuentoAplicado = (saldoCuenta * descuento) / 100;
      const montoAPagar = saldoCuenta - descuentoAplicado;
  
      // Actualizar los valores en el formulario
      setFormData({ ...formData, cuenta: cuentaSeleccionada });
  
      // Actualizar los inputs correspondientes
      document.getElementById("saldoCuenta").value = saldoCuenta.toFixed(2);
      document.getElementById("descuentoAplicado").value = descuentoAplicado.toFixed(2);
      document.getElementById("montoAPagar").value = montoAPagar.toFixed(2);
    } catch (error) {
      Swal.fire('Error', 'No se pudo obtener el saldo de la cuenta.', 'error');
    }
  };
  
  const handleDescuentoChange = (e) => {
    let descuento = parseFloat(e.target.value);
  
    // Validar que el descuento sea un número positivo
    if (isNaN(descuento) || descuento < 0) {
      descuento = 0; // Si no es válido, establecer el descuento en 0
      Swal.fire({
        icon: 'warning',
        title: 'Descuento no válido',
        text: 'Ingrese un número positivo para el descuento.',
      });
    }
  
    const saldoCuenta = parseFloat(document.getElementById("saldoCuenta").value) || 0;
  
    const descuentoAplicado = (saldoCuenta * descuento) / 100;
    const montoAPagar = saldoCuenta - descuentoAplicado;
  
    setFormData({ ...formData, descuento });
  
    // Actualizar los inputs correspondientes
    document.getElementById("descuentoAplicado").value = descuentoAplicado.toFixed(2);
    document.getElementById("montoAPagar").value = montoAPagar.toFixed(2);
  };
  
  
  useEffect(() => {
    const decryptCampanaId = async (encryptedValue) => {
      try {
        const token = getToken();
        if (!token) return;
  
        const response = await axios.post(
          `${config.API_BASE_URL}/decrypt`,
          { encrypted_value: encryptedValue },
          {
            headers: {
              Authorization: `Bearer ${token}`,
            },
          }
        );
        return response.data.decrypted_value;
      } catch (error) {
        Swal.fire({
          icon: 'error',
          title: 'Error de Desencriptado',
          text: 'No se pudo desencriptar el valor.',
        });
        throw error;
      }
    };
  
    const fetchDropdownOptions = async (ddlValue, setStateCallback, campanaId) => {
      try {
        const token = getToken();
        if (!token) return;
    
        const response = await axios.post(
          `${config.API_BASE_URL}/drops`,
          { id_campana: campanaId, ddl: ddlValue },
          {
            headers: {
              Authorization: `Bearer ${token}`,
            },
          }
        );
    
        setStateCallback(Array.isArray(response.data) ? response.data : []);
      } catch (error) {
        Swal.fire('Error', `No se pudieron obtener los datos del listado: ${ddlValue}.`, 'error');
      }
    };

    const fetchDropdownCuenta = async (ddlValue, setStateCallback, GestionId) => {
      try {
        const token = getToken();
        if (!token) return;
    
        const response = await axios.post(
          `${config.API_BASE_URL}/drops`,
          { valor_int1: GestionId, ddl: ddlValue },
          {
            headers: {
              Authorization: `Bearer ${token}`,
            },
          }
        );
    
        setStateCallback(Array.isArray(response.data) ? response.data : []);
      } catch (error) {
        Swal.fire('Error', `No se pudieron obtener los datos del listado: ${ddlValue}.`, 'error');
      }
    };
     
    const loadData = async () => {
      const urlParams = new URLSearchParams(window.location.search);
      const encryptedCampanaId = urlParams.get('campana');
      const encryptedGestinoId = urlParams.get('id_gestion');
      const encryptedidUsuario = urlParams.get('id');
  
      if (encryptedCampanaId) {
        const campanaId = await decryptCampanaId(encryptedCampanaId);
        if (campanaId) {
          setIdCampana(campanaId);
          fetchDropdownOptions('TIPO_GESTION', setTipoGestionOptions, campanaId);
          fetchDropdownOptions('TIPOLOGIA', setTipologiaOptions, campanaId);
          fetchDropdownOptions('TIPO_DESCUENTO', setTipoDescuentoOptions, campanaId);
        }
        
      } else {
        Swal.fire('Error', 'No se encontró el parámetro campana en la URL.', 'error');
      }

      if (encryptedGestinoId) {
        const GestionId = await decryptCampanaId(encryptedGestinoId);
        if (GestionId) {
          setIdGestion(GestionId);
          fetchDropdownCuenta('LISTADO_CUENTAS', setCuentaOptions, GestionId);
        }
        
      } else {
        Swal.fire('Error', 'No se encontró el parámetro campana en la URL.', 'error');
      }

      if (encryptedidUsuario) {
        const UsuarioId = await decryptCampanaId(encryptedidUsuario);
        if (UsuarioId) {
          setidUsuario(UsuarioId);      
        }
        
      } else {
        Swal.fire('Error', 'No se encontró el parámetro campana en la URL.', 'error');
      }
    };
  
    loadData();
    
  }, []);

  useEffect(() => {
    const handleBeforeUnload = (event) => {
      event.preventDefault();
      event.returnValue = ''; // Obligatorio para mostrar la alerta nativa
    };
  
    window.addEventListener('beforeunload', handleBeforeUnload);
  
    return () => {
      window.removeEventListener('beforeunload', handleBeforeUnload);
    };
  }, []);

  useEffect(() => {
    const handlePopState = (event) => {
      Swal.fire({
        title: '¿Estás seguro?',
        text: 'Si sales de este formulario, se perderán los datos ingresados.',
        icon: 'warning',
        showCancelButton: true,
        confirmButtonText: 'Salir',
        cancelButtonText: 'Cancelar',
      }).then((result) => {
        if (result.isConfirmed) {
          // Permitir la navegación hacia atrás
          window.history.back();
        } else {
          // Bloquear la navegación hacia atrás
          window.history.pushState(null, '', window.location.href);
        }
      });
    };
  
    window.addEventListener('popstate', handlePopState);
  
    return () => {
      window.removeEventListener('popstate', handlePopState);
    };
  }, []);
  
  return (
    <div className="container mt-5">
    <div className="card shadow">
      <div className="card-header text-center">
        <h4>Registrar Gestión</h4>
        <button type="button" className="btn btn-secondary" onClick={redirectForm}>
          Regresar
        </button>
      </div>
      <div className="card-body">
        <form id="gestionForm">
          <div className="row mb-3">
            <div className="col-md-4">
              <label htmlFor="tipoGestion" className="form-label">
                Tipo de Gestión
              </label>
              <select
                className="form-select"
                id="tipoGestion"
                value={formData.tipoGestion}
                onChange={handleInputChange}
                required
              >
                <option value="" disabled>
                  Seleccione una opción
                </option>
                {Array.isArray(tipologiaOptions) &&
                tipoGestionOptions.map((option) => (
                  <option key={option.VALUE} value={option.VALUE}>
                    {option.ITEM}
                  </option>
                ))}
              </select>
            </div>
            <div className="col-md-4">
              <label htmlFor="tipologia" className="form-label">
                Tipología
              </label>
              <select
  className="form-select"
  id="tipologia"
  value={formData.tipologia}
  onChange={handleTipologiaChange}
  required
>
  <option value="" disabled>
    Seleccione una opción
  </option>
  {Array.isArray(tipologiaOptions) &&
    tipologiaOptions.map((option) => (
      <option key={option.VALUE} value={option.VALUE}>
        {option.ITEM}
      </option>
    ))}
</select>

            </div>
            <div className="col-md-4">
              <label htmlFor="subtipologia" className="form-label">
                Subtipología
              </label>
              <select
                className="form-select"
                id="subtipologia"
                value={formData.subtipologia}
                onChange={(e) => setFormData({ ...formData, subtipologia: e.target.value })}
                required
              >
                <option value="" disabled>
                  Seleccione una opción
                </option>
                {Array.isArray(tipologiaOptions) &&
                subtipologiaOptions.map((option) => (
                  <option key={option.VALUE} value={option.VALUE}>
                    {option.ITEM}
                  </option>
                ))}
              </select>
            </div>
          </div>
          <div className="row mb-3">
            <div className="col-md-4">
              <label htmlFor="razon_mora" className="form-label">
                Razón de mora
              </label>
              <select
                className="form-select"
                id="razonMora"
                value={formData.razonMora}
                onChange={(e) => setFormData({ ...formData, razonMora: e.target.value })}
                required
              >
                <option value="" disabled>
                  Seleccione una opción
                </option>
                {razonMoraOptions.map((option) => (
                  <option key={option.VALUE} value={option.VALUE}>
                    {option.ITEM}
                  </option>
                ))}
              </select>
            </div>
            <div className="col-md-4">
              <label htmlFor="tipo_contacto" className="form-label">
                Tipo de contacto
              </label>
              <select
                className="form-select"
                id="tipoContacto"
                value={formData.tipoContacto}
                onChange={(e) => setFormData({ ...formData, tipoContacto: e.target.value })}
                required
              >
                <option value="" disabled>
                  Seleccione una opción
                </option>
                {tipoContactoOptions.map((option) => (
                  <option key={option.VALUE} value={option.VALUE}>
                    {option.ITEM}
                  </option>
                ))}
              </select>
            </div>
          </div>

          <div className="row mb-3">
          <div className="col-md-6">
            <label htmlFor="observaciones" className="form-label">
              Observaciones
            </label>
            <textarea
              className="form-control"
              id="observaciones"
              rows="3"
              required
              value={formData.observaciones} // Enlazar al estado
              onChange={(e) => setFormData({ ...formData, observaciones: e.target.value })} // Actualizar el estado
            ></textarea>
          </div>
          <div className="col-md-6">
            <label htmlFor="investigacion" className="form-label">
              Investigación
            </label>
            <textarea
              className="form-control"
              id="investigacion"
              rows="3"
              required
              value={formData.investigacion} // Enlazar al estado
              onChange={(e) => setFormData({ ...formData, investigacion: e.target.value })} // Actualizar el estado
            ></textarea>
          </div>

          </div>

          <div className="card-header text-center">
            <h4>Promesas de pago</h4>
          </div>

          <div className="row mb-3">
            <div className="col-md-4">
              <label htmlFor="cuenta" className="form-label">
                Cuenta
              </label>
              <select
                className="form-select"
                id="cuenta"
                value={formData.cuenta}
                onChange={handleCuentaChange}
                required
              >
                <option value="" disabled>
                  Seleccione una opción
                </option>
                {cuentaOptions.map((cuenta) => (
                  <option key={cuenta.VALUE} value={cuenta.VALUE}>
                    {cuenta.ITEM}
                  </option>
                ))}
              </select>
            </div>
            <div className="col-md-4">
              <label htmlFor="cantidad-cuotas" className="form-label">
                Cant. Cuotas
              </label>
              <input
                type="number"
                className="form-control"
                id="cantidadCuotas"
                placeholder="Ingrese el numero de cuotas"
                required
                value={formData.cantidadCuotas}
                onChange={(e) => {
                  const value = parseInt(e.target.value, 10);
                  if (!isNaN(value) && value > 0) {
                    setFormData({ ...formData, cantidadCuotas: value });
                  } else if (e.target.value === '') {
                    setFormData({ ...formData, cantidadCuotas: '' });
                  }
                }}
              />
            </div>
            <div className="col-md-4">
              <label htmlFor="fecha-pago" className="form-label">
                Fecha de pago
              </label>
              <input
                type="date"
                className="form-control"
                id="fecha-pago"
                placeholder="Ingrese la fecha de pago"
                required
                value={formData.fechaPago}
                onChange={(e) => setFormData({ ...formData, fechaPago: e.target.value })}
              />
            </div>
          </div>

          <div className="row mb-3">
            <div className="col-md-6">
              <label htmlFor="descuento" className="form-label">
                Descuento (%)
              </label>
              <input
                type="number"
                className="form-control"
                id="descuento"
                placeholder="Ingrese el descuento en porcentaje"
                required
                onChange={handleDescuentoChange}
                value={formData.descuento}
              />
            </div>
            <div className="col-md-6">
              <label htmlFor="tipoDescuento" className="form-label">
                Tipo de Descuento
              </label>
              <select
                className="form-select"
                id="tipoDescuento"
                value={formData.tipoDescuento}
                onChange={(e) => setFormData({ ...formData, tipoDescuento: e.target.value })}
                required
              >
                <option value="" disabled>
                  Seleccione una opción
                </option>
                {Array.isArray(tipologiaOptions) &&
                tipoDescuentoOptions.map((option) => (
                  <option key={option.VALUE} value={option.VALUE}>
                    {option.ITEM}
                  </option>
                ))}
              </select>
            </div>
          </div>

          <div className="text-center mb-4">

          </div>

          <div className="text-center">
            <h3>Previsualización de cálculos</h3>
          </div>

          <div className="row mb-3 mt-3">
            <div className="col-md-4">
              <label className="form-label">Saldo de la cuenta:</label>
              <input type="number" id="saldoCuenta" className="form-control" readOnly />
            </div>
            <div className="col-md-4">
              <label className="form-label">Descuento aplicado:</label>
              <input type="number" id="descuentoAplicado" className="form-control" readOnly />
            </div>
            <div className="col-md-4">
              <label className="form-label">Monto a pagar:</label>
              <input type="number" id="montoAPagar" className="form-control" readOnly />
            </div>
          </div>


          <div className="text-center mb-4">
            <button
              type="button"
              className="btn btn-primary"
              onClick={handleAgregarPromesa}
            >
              Agregar Promesa
            </button>
          </div>

          <div className="table-responsive">
            <table className="table table-bordered" id="tablaPromesas">
              <thead>
                <tr>
                  <th>Cuenta</th>
                  <th>Cant. Cuotas</th>
                  <th>Fecha de Pago</th>
                  <th>Descuento</th>
                  <th>Tipo de Descuento</th>
                  <th>Acciones</th>
                </tr>
              </thead>
              <tbody>
              {promesas.map((promesa, index) => (
                <tr key={index}>
                  <td>{promesa.cuenta}</td>
                  <td>{promesa.cantidadCuotas}</td>
                  <td>{promesa.fechaPago}</td>
                  <td>{promesa.descuento}</td>
                  <td>{promesa.tipoDescuento}</td>
                  <td>
                    <button
                      className="btn btn-danger btn-sm"
                      onClick={() => handleEliminarPromesa(index)}
                    >
                      Eliminar
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>

            </table>
          </div>

          <div className="text-center">
            <div className="text-center">
              <button type="button" className="btn btn-success" onClick={registrarGestion}>
                Registrar Gestión
              </button>
            </div>

          </div>
        </form>
      </div>
    </div>
  </div>
  );
};

export default App;
